<?php
use Illuminate\Support\Facades\DB;
// Included only by the isolated native tracking runner, after its fixture setup.
$before=$count;
DB::table('mapa_tracking_devices')->where('id',$device['id'])->update(['revoked_at'=>null]);
$driverCount=DB::table('mapa_mobile_driver_states')->count();
$historyCount=DB::table('mapa_device_position_history')->count();
$hardwareNow=(int)round(microtime(true)*1000);
$hardwareFix=['latitude'=>18.31,'longitude'=>82.88,'accuracy_m'=>8,'recorded_at'=>$hardwareNow-500];
$positionCount=DB::table('positions')->count();
$answer=$service->ingest(trackingRequest($hardwareFix,$device['secret']));
check($answer['map_updated']===true,'valid hardware fix projects native vehicle');
$native=Fleetbase\FleetOps\Models\Vehicle::withoutGlobalScopes()->where('company_uuid',$company)->where('uuid',$vehicle)->first();
check(abs($native->location->getLat()-18.31)<0.00001,'native map receives hardware latitude');
check(abs($native->location->getLng()-82.88)<0.00001,'native map receives hardware longitude');
check(!$native->online,'hardware cannot start ambulance duty');
check(DB::table('mapa_mobile_driver_states')->count()===$driverCount,'hardware never proves driver GPS');
check(DB::table('positions')->count()===$positionCount+1,'native position history receives valid hardware sample');
check(DB::table('mapa_device_position_history')->count()===$historyCount+1,'device history preserves source fix');
$stored=DB::table('mapa_device_position_history')->orderByDesc('id')->first();
check($stored->vehicle_uuid===$vehicle && $stored->company_uuid===$company,'hardware history tenant and ambulance derived from credential');
check((int)$stored->recorded_at===$hardwareFix['recorded_at'] && (int)$stored->received_at>=$hardwareFix['recorded_at'],'device and receipt timestamps distinct');
denied(fn()=>$service->ingest(trackingRequest($hardwareFix,$device['secret'])),422);
check(DB::table('mapa_device_position_history')->count()===$historyCount+1,'duplicate sample cannot inflate history');
// A real crew mutation in this disposable database exercises both projection paths.
$crewUser=row('users',['company_uuid'=>$company,'email'=>'DEMO-projection-crew@example.invalid','password'=>Illuminate\Support\Facades\Hash::make('DEMO-local-only'),'email_verified_at'=>now(),'status'=>'active']);
row('company_users',['company_uuid'=>$company,'user_uuid'=>$crewUser,'status'=>'active']);
$crewDriver=row('drivers',['company_uuid'=>$company,'user_uuid'=>$crewUser,'vehicle_uuid'=>$vehicle,'online'=>true,'location'=>DB::raw("ST_GeomFromText('POINT(82.89 18.35)')")]);
DB::table('mapa_mobile_bindings')->insert(['id'=>(string)Illuminate\Support\Str::uuid(),'company_uuid'=>$company,'user_uuid'=>$crewUser,'driver_uuid'=>$crewDriver,'role'=>'crew','enabled'=>true,'revision'=>1,'created_at'=>now(),'updated_at'=>now()]);
$crewToken=$mobile->login(trackingRequest(['email'=>'demo-projection-crew@example.invalid','password'=>'DEMO-local-only']))['token'];
$phoneFix=['latitude'=>18.35,'longitude'=>82.89,'accuracy_m'=>6,'recorded_at'=>$hardwareNow+2000,'mock_location'=>false,'action_id'=>'DEMO_projection_phone_1'];
$phoneAnswer=$mobile->mutate(trackingRequest($phoneFix,$crewToken),'gps');
check($phoneAnswer['map_updated']===true,'newer phone projects native vehicle');
$state=DB::table('mapa_vehicle_position_states')->where('vehicle_uuid',$vehicle)->first();
check($state->source==='crew_phone' && $state->source_id===$crewDriver,'projection source identifies crew independently of tracker');
$positionsAfterPhone=DB::table('positions')->count();
$answer=$service->ingest(trackingRequest([...$hardwareFix,'latitude'=>18.32,'recorded_at'=>$hardwareNow],$device['secret']));
check($answer['map_updated']===false,'older hardware cannot replace newer verified phone fix');
check(DB::table('positions')->count()===$positionsAfterPhone,'older hardware avoids native map regression');
check(DB::table('mapa_device_position_history')->count()===$historyCount+2,'older-than-phone sample retains separate hardware evidence');
$answer=$service->ingest(trackingRequest([...$hardwareFix,'latitude'=>18.37,'recorded_at'=>$hardwareNow+4000],$device['secret']));
check($answer['map_updated']===true,'newer hardware replaces phone projection');
$positionsBeforeDelayedPhone=DB::table('positions')->count();
$vehicleEvents=Illuminate\Support\Facades\Event::dispatched(App\MapaMobile\CrewVehicleLocationChanged::class)->count();
$driverEvents=Illuminate\Support\Facades\Event::dispatched(App\MapaMobile\CrewDriverLocationChanged::class)->count();
$phoneAnswer=$mobile->mutate(trackingRequest([...$phoneFix,'latitude'=>18.36,'recorded_at'=>$hardwareNow+3000,'action_id'=>'DEMO_projection_phone_2'],$crewToken),'gps');
check($phoneAnswer['map_updated']===false,'delayed phone cannot replace newer hardware projection');
$native=Fleetbase\FleetOps\Models\Vehicle::withoutGlobalScopes()->where('uuid',$vehicle)->first();
check(abs($native->location->getLat()-18.37)<0.00001,'delayed phone leaves hardware vehicle coordinates intact');
$driver=Fleetbase\FleetOps\Models\Driver::withoutGlobalScopes()->where('uuid',$crewDriver)->first();
check(abs($driver->location->getLat()-18.36)<0.00001,'delayed phone still updates its own driver coordinates');
check(DB::table('positions')->count()===$positionsBeforeDelayedPhone+1,'delayed phone adds only driver native history');
check((int)DB::table('mapa_mobile_driver_states')->where('driver_uuid',$crewDriver)->value('recorded_at')===$hardwareNow+3000,'delayed phone preserves fresh driver evidence');
check($phoneAnswer['gps_evidence']['recorded_at']===$hardwareNow+3000,'delayed phone immutable receipt preserves capture time');
check(Illuminate\Support\Facades\Event::dispatched(App\MapaMobile\CrewVehicleLocationChanged::class)->count()===$vehicleEvents,'delayed phone does not broadcast a regressed vehicle');
check(Illuminate\Support\Facades\Event::dispatched(App\MapaMobile\CrewDriverLocationChanged::class)->count()===$driverEvents+1,'delayed phone still broadcasts its driver fix');
check($driver->online && !$native->online,'projection never alters driver or vehicle duty');
$service->revokeDevice(trackingRequest([],$admin),$device['id']);
$replacement=$service->createDevice(trackingRequest(['vehicle_id'=>$vid,'external_id'=>'DEMO-IMEI-replacement','label'=>'DEMO replacement tracker'],$admin));
$positionsBeforeReplacement=DB::table('positions')->count();
$answer=$service->ingest(trackingRequest([...$hardwareFix,'recorded_at'=>$hardwareNow+3500],$replacement['secret']));
check($answer['map_updated']===false,'replacement tracker cannot reset vehicle ordering');
check(DB::table('positions')->count()===$positionsBeforeReplacement,'older replacement sample adds no native map history');
check(DB::table('mapa_device_position_history')->where('device_id',$replacement['id'])->count()===1,'replacement evidence remains recorded even if not projected');
$answer=$service->ingest(trackingRequest([...$hardwareFix,'recorded_at'=>$hardwareNow+4000],$replacement['secret']));
check($answer['map_updated']===false,'equal source timestamps keep existing vehicle projection');
$answer=$service->ingest(trackingRequest([...$hardwareFix,'latitude'=>18.38,'recorded_at'=>$hardwareNow+5000],$replacement['secret']));
check($answer['map_updated']===true,'newer replacement sample may advance shared projection');
$finalPositions=DB::table('positions')->count();
denied(fn()=>$service->ingest(trackingRequest([...$hardwareFix,'recorded_at'=>$hardwareNow+6000],$device['secret'])),401);
check(DB::table('positions')->count()===$finalPositions,'revoked tracker cannot change native history');
DB::table('vehicles')->where('uuid',$vehicle)->update(['status'=>'inactive']);
denied(fn()=>$service->ingest(trackingRequest([...$hardwareFix,'recorded_at'=>$hardwareNow+6000],$replacement['secret'])),409);
check(DB::table('positions')->count()===$finalPositions,'inactive ambulance cannot change map');
echo ($count-$before)." hardware history and native projection checks passed.\n";
